function Logo({ small = false }: { small?: boolean }) { return <span className="brand-mark"><span className="brand-icon" />{!small && <span>AI Chat Analyzer</span>}</span>; }
function Avatar({ name, color = "blue" }: { name: string; color?: "blue" | "yellow" }) { return <span className={`avatar ${color}`}>{name.slice(0, 1).toUpperCase()}</span>; }
function delay(ms: number) { return new Promise((resolve) => setTimeout(resolve, ms)); }
function prettyCount(value: number) { return value.toLocaleString("zh-TW"); }
function percent(value: number) { return `${Math.round(value)}%`; }
function shortName(name: string) { return name.length > 10 ? `${name.slice(0, 10)}…` : name; }
function maxValue(values: number[]) { return Math.max(1, ...values); }
function levelText(score: number) { return score >= 70 ? "高" : score >= 45 ? "中" : "低"; }
function dateInputValue(value?: string) { return value ? value.slice(0, 10) : ""; }
function filteredByRange(messages: NormalizedMessage[], range: AnalysisRange) {
  if (range.preset === "all") return messages;
  const now = new Date(); let start: Date | undefined; let end: Date | undefined;
  if (range.preset === "thisYear") start = new Date(now.getFullYear(), 0, 1);
  if (range.preset === "lastYear") { start = new Date(now.getFullYear() - 1, 0, 1); end = new Date(now.getFullYear(), 0, 1); }
  if (range.preset === "last12") { start = new Date(now); start.setFullYear(start.getFullYear() - 1); }
  if (range.preset === "custom") { start = range.start ? new Date(`${range.start}T00:00:00`) : undefined; end = range.end ? new Date(`${range.end}T23:59:59`) : undefined; }
  return messages.filter((message) => { const timestamp = Date.parse(message.timestamp); return (!start || timestamp >= start.getTime()) && (!end || timestamp <= end.getTime()); });
}
function rangeLabel(range: AnalysisRange) { return range.preset === "all" ? "全部紀錄" : range.preset === "thisYear" ? "今年" : range.preset === "lastYear" ? "去年" : range.preset === "last12" ? "最近一年" : `${range.start ?? "開始"}–${range.end ?? "現在"}`; }

